public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    int start = 0;
    Set<String> seen = new HashSet<>();

    while (start < s.length()) {
        for (int end = start; end < s.length(); end++) {
            String sub = s.substring(start, end + 1);
            if (!seen.contains(sub)) {
                seen.add(sub);
                maxUnique++;
                start = end + 1;
                break;
            }
        }
    }

    return maxUnique;
}

